      <p className="text-base font-medium mb-1">{title}</p>
      <p className="text-sm text-[#8a8a8a] dark:text-[#9a9a9a]">{subtitle}</p>
    </div>
  )
}

import { openDB, IDBPDatabase } from 'idb'
import type { Habit, HabitCompletion, MoodEntry } from './types'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

const STORES = {
  habits: 'habits',
  completions: 'completions',
  moods: 'moods',
} as const

let _db: IDBPDatabase | null = null

async function getDB(): Promise<IDBPDatabase> {
  if (_db) return _db
  _db = await openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORES.habits)) {
        const store = db.createObjectStore(STORES.habits, { keyPath: 'id' })
        store.createIndex('byName', 'name')
      }
      if (!db.objectStoreNames.contains(STORES.completions)) {
        const store = db.createObjectStore(STORES.completions, { keyPath: 'id' })
        store.createIndex('byDate', 'date')
        store.createIndex('byDateHabit', ['date', 'habitId'])
      }
      if (!db.objectStoreNames.contains(STORES.moods)) {
        const store = db.createObjectStore(STORES.moods, { keyPath: 'date' })
      }
    },
  })
  return _db
}

